import{_ as e,o,c as t,a6 as i}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Entre na sua conta do Cloud","description":"","frontmatter":{"title":"Entre na sua conta do Cloud","docId":"user.cloud.account","translationKey":"user.cloud.account","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"02b7718e7fc7b2a53b68ee1c6e19e622608a6fdfc7eac553879c474ca69ea74b","translationRevision":"78ce7c124fefac65fc37718d87fb15fd386130fc9a16414febfc481f33749dba","order":10},"headers":[],"relativePath":"pt/user/cloud/account.md","filePath":"pt/user/cloud/account.md","lastUpdated":1794611623000}'),r={name:"pt/user/cloud/account.md"};function n(s,a,d,c,l,u){return o(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="sign-in-to-your-cloud-account" tabindex="-1">Entre na sua conta do Cloud <a class="header-anchor" href="#sign-in-to-your-cloud-account" aria-label="Permalink to &quot;Entre na sua conta do Cloud {#sign-in-to-your-cloud-account}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Conecte o aplicativo de desktop ao serviço Cloud configurado para operações de catálogo e colaboração baseadas em conta. Você precisa de acesso à rede, um navegador do sistema e um armazenamento de credenciais do sistema operacional funcional. A edição local continua útil sem o Cloud; uma sessão do Cloud não autentica sua conexão com a LIVE do TikTok.</p><h2 id="sign-in-and-verify-identity" tabindex="-1">Entre e verifique a identidade <a class="header-anchor" href="#sign-in-and-verify-identity" aria-label="Permalink to &quot;Entre e verifique a identidade {#sign-in-and-verify-identity}&quot;">​</a></h2><ol><li>Abra <strong>Settings → Account</strong>. Leia o estado atual antes de iniciar outro login.</li><li>Selecione <strong>Sign in</strong>. O desktop inicia um receptor local de retorno e abre a página de login configurada no navegador do sistema.</li><li>Conclua o fluxo de login do serviço e retorne ao TikTools. Se o navegador não abrir, use a URL de login mostrada pelo aplicativo para esta tentativa. Trate essa URL como privada e não a publique.</li><li>Aguarde o estado da conta indicar que a sessão está iniciada. Confirme o nome ou e-mail exibido antes de abrir um catálogo privado ou equipe.</li><li>Expanda os diagnósticos de Account se o status informar um erro. Use <strong>Cancel</strong> para abandonar uma tentativa inacabada em vez de deixar várias tentativas ativas.</li><li>Ao terminar em um computador compartilhado, selecione <strong>Sign out</strong> e verifique se o estado da conta mudou.</li></ol><p>O host nativo gerencia o token da sessão. Ele armazena credenciais pelo armazenamento de credenciais do sistema operacional e mantém apenas status não secreto no frontend. Não existe alternativa em arquivo de texto simples quando o armazenamento seguro está indisponível. Uma pasta de dados copiada não é uma sessão autenticada portátil.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>Login, restauração e saída nativos estão disponíveis em hosts compilados com autenticação do Cloud. Uma conta configurada pode ser restaurada ao reiniciar e revalidada com o serviço. Um host não configurado ou incompatível não se corrige fornecendo um cookie diferente do TikTok.</p><p>A disponibilidade do login do serviço e a aceitação real por provedor/plataforma dependem do serviço implantado e da sua máquina. A validação local não comprova que todas as rotas de login de produção funcionam.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperação {#recovery}&quot;">​</a></h2><p>Para uma tentativa cancelada ou expirada, inicie um login novo após fechar o anterior. Para erros de rede ou serviço, preserve o código de diagnóstico e tente novamente após a recuperação. Para um erro do armazenamento de credenciais, restaure a disponibilidade do armazenamento seguro do sistema operacional; não cole um token de portador nas configurações nem em uma mensagem de suporte. Consulte <a href="./changes.html">Changes</a> para sincronização explícita e <a href="./collaboration.html">colaboração</a> para concessões de acesso separadas.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalhes de operação {#operational-details}&quot;">​</a></h2><p>Sair apaga credenciais locais e limpa o contexto antes de tentar revogação remota de melhor esforço. A interface desconectada confirma remoção local, não revogação remota durante falha de rede. Use administração de sessões do serviço se disponível. Exporte Diagnostics antes de sair/trocar conta conhecida: esse histórico UI é apagado. Cookies TikTok e sessões de host remoto são identidades separadas.</p>',13)])])}const g=e(r,[["render",n]]);export{m as __pageData,g as default};
